nextflow_process {

    name "Test Process SENTIEON_COVERAGEMETRICS"
    tag "modules_nfcore"
    tag "modules"
    tag "sentieon"
    tag "coveragemetrics"
    tag "sentieon/coveragemetrics"

    script "../main.nf"
    process "SENTIEON_COVERAGEMETRICS"
    config "./nextflow.config"

    test("Test per sample") {
        when {
            params {
                module_args = ''
                module_args2 = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'], []]
                input[2] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[3] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                input[4] = [[id: 'test'], []]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("Test with interval") {
        when {
            params {
                module_args = ''
                module_args2 = ''
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/bed/test.bed')]
                input[2] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[3] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                input[4] = [[id: 'test'], []]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("Test omit outputs") {
        when {
            params {
                module_args = ''
                module_args2 = '--omit_sample_stat --omit_locus_stat --omit_interval_stat'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true) ],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam.bai', checkIfExists: true) ]
                ]
                input[1] = [[id: 'test'], []]
                input[2] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)]
                input[3] = [[id: 'test'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta.fai', checkIfExists: true)]
                input[4] = [[id: 'test'], []]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("Test readgroup partition") {
        when {
            params {
                module_args = ''
                module_args2 = '--partition sample,platform,library,center'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
